const snapshotRiskScores = `-- name: SnapshotRiskScores :execrows
INSERT INTO risk_snapshots (day, subject_type, subject_id, score, grade, cards)
SELECT $1::date, s.subject_type, s.subject_id, s.score, s.grade, coalesce(s.result -> 'cards', '[]'::jsonb)
FROM risk_scores s
ON CONFLICT (subject_type, subject_id, day) DO NOTHING
`

// De momentopname van vandaag, één keer per dag per onderwerp.
func (q *Queries) SnapshotRiskScores(ctx context.Context, day pgtype.Date) (int64, error) {
	result, err := q.db.Exec(ctx, snapshotRiskScores, day)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertRiskScore = `-- name: UpsertRiskScore :exec
INSERT INTO risk_scores (subject_type, subject_id, score, grade, result, computed_at, announced_grade, grade_since)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
ON CONFLICT (subject_type, subject_id) DO UPDATE
SET score = EXCLUDED.score, grade = EXCLUDED.grade, result = EXCLUDED.result, computed_at = EXCLUDED.computed_at,
    announced_grade = EXCLUDED.announced_grade, grade_since = EXCLUDED.grade_since
`

type UpsertRiskScoreParams struct {
	SubjectType    string
	SubjectID      uuid.UUID
	Score          *int32
	Grade          string
	Result         []byte
	ComputedAt     time.Time
	AnnouncedGrade string
	GradeSince     time.Time
}

func (q *Queries) UpsertRiskScore(ctx context.Context, arg UpsertRiskScoreParams) error {
	_, err := q.db.Exec(ctx, upsertRiskScore,
		arg.SubjectType,
		arg.SubjectID,
		arg.Score,
		arg.Grade,
		arg.Result,
		arg.ComputedAt,
		arg.AnnouncedGrade,
		arg.GradeSince,
	)
	return err
}
